import React, { createContext, ReactNode, useContext } from "react";
import { Button, ButtonProps } from "@arco-design/web-react";
import {
  IconDelete,
  IconDown,
  IconUp,
  IconPlus,
  IconMenu,
  IconCopy,
  IconProps,
} from "@arco-design/web-react/icon";
import { ArrayField } from "@formily/core";
import {
  useField,
  useFieldSchema,
  Schema,
  JSXComponent,
  RecordScope,
  RecordsScope,
} from "@formily/react";
import { isValid, clone } from "@formily/shared";
import { SortableHandle } from "react-sortable-hoc";
import { usePrefixCls } from "../__builtins__";
import cls from "classnames";

export interface IArrayBaseAdditionProps extends ButtonProps {
  title?: string;
  method?: "push" | "unshift";
  defaultValue?: any;
}

export interface IArrayBaseContext {
  props: IArrayBaseProps;
  field: ArrayField;
  mode: "jsx" | "schema";
  schema: Schema;
}

export interface IArrayBaseItemProps {
  index: number;
  record: ((index: number) => Record<string, any>) | Record<string, any>;
}

export type ArrayBaseMixins = {
  Addition?: React.FC<React.PropsWithChildren<IArrayBaseAdditionProps>>;
  Copy?: React.FC<React.PropsWithChildren<IconProps & { index?: number }>>;
  Remove?: React.FC<React.PropsWithChildren<IconProps & { index?: number }>>;
  MoveUp?: React.FC<React.PropsWithChildren<IconProps & { index?: number }>>;
  MoveDown?: React.FC<React.PropsWithChildren<IconProps & { index?: number }>>;
  SortHandle?: React.FC<
    React.PropsWithChildren<IconProps & { index?: number; iconNode?: React.ReactElement }>
  >;
  Index?: React.FC;
  useArray?: () => IArrayBaseContext;
  useIndex?: (index?: number) => number;
  useRecord?: (record?: number) => any;
  useAddition?: (
    method?: "push" | "unshift",
    defaultValue?: any
  ) => {
    addItem: () => void;
    showAdd: boolean;
    disabled?: boolean;
    currentCount: number;
    title?: ReactNode;
  };
  useRemove?: (
    index?: number
  ) => {
    removeItem: () => void;
    index: number;
    showRemove: boolean;
    disabled?: boolean;
  };
};

export interface IArrayBaseProps {
  mode: "jsx" | "schema";
  disabled?: boolean;
  onAdd?: (index: number) => void;
  onCopy?: (index: number) => void;
  onRemove?: (index: number) => void;
  onMoveDown?: (index: number) => void;
  onMoveUp?: (index: number) => void;
}

type ComposedArrayBase = React.FC<React.PropsWithChildren<IArrayBaseProps>> &
  ArrayBaseMixins & {
    Item: React.FC<React.PropsWithChildren<IArrayBaseItemProps>>;
    mixin: <T extends JSXComponent>(target: T) => T & ArrayBaseMixins;
  };

// @ts-ignore
const ArrayBaseContext = createContext<IArrayBaseContext>(null);
// @ts-ignore
const ItemContext = createContext<IArrayBaseItemProps>(null);

const takeRecord = (val: any, index?: number) =>
  typeof val === "function" ? val(index) : val;

const useArray = () => useContext(ArrayBaseContext);

const useIndex = (index?: number): number => {
  const ctx = useContext(ItemContext);
  return ctx ? ctx.index : (index as number);
};

const useRecord = (record?: number) => {
  const ctx = useContext(ItemContext);
  return takeRecord(ctx ? ctx.record : record, ctx?.index);
};

const getSchemaDefaultValue = (schema?: Schema): any => {
  if (schema?.type === "array") {
    return [];
  }
  if (schema?.type === "object") {
    return {};
  }
  if (schema?.type === "void") {
    for (const key in schema.properties) {
      const value = getSchemaDefaultValue(schema.properties[key]);
      if (isValid(value)) {
        return value;
      }
    }
  }
};

const getDefaultValue = (defaultValue: any, schema: Schema) => {
  if (isValid(defaultValue)) {
    return clone(defaultValue);
  }
  if (Array.isArray(schema?.items)) {
    return getSchemaDefaultValue(schema?.items[0]);
  }
  return getSchemaDefaultValue(schema?.items);
};

export const ArrayBase: ComposedArrayBase = (props) => {
  const field = useField<ArrayField>();
  const schema = useFieldSchema();
  return (
    <RecordsScope getRecords={() => field.value}>
      <ArrayBaseContext.Provider
        value={{ field, schema, props, mode: props.mode }}
      >
        {props.children}
      </ArrayBaseContext.Provider>
    </RecordsScope>
  );
};

ArrayBase.Item = ({ children, ...props }) => {
  const { index } = props;
  const record = takeRecord(props.record, props.index);
  return (
    <ItemContext.Provider value={props}>
      <RecordScope getIndex={() => index} getRecord={() => record}>
        {children}
      </RecordScope>
    </ItemContext.Provider>
  );
};

ArrayBase.Item.displayName = "ArrayItem";

const SortHandle = SortableHandle((props: any) => {
  const prefixCls = usePrefixCls("formily-array-base");
  if (props.iconNode) {
    return props.iconNode;
  }
  return (
    <IconMenu
      {...props}
      className={cls(`${prefixCls}-sort-handle`, props.className)}
      style={{ ...props.style }}
    />
  );
}) as any;

ArrayBase.SortHandle = (props) => {
  const array = useArray();
  if (!array) {
    return null;
  }
  if (array.field?.pattern !== "editable") {
    return null;
  }
  return <SortHandle {...props} />;
};

ArrayBase.SortHandle.displayName = "ArraySortHandle";

ArrayBase.Index = (props) => {
  const index = useIndex();
  const prefixCls = usePrefixCls("formily-array-base");
  return (
    <span {...props} className={`${prefixCls}-index`}>
      #{index + 1}.
    </span>
  );
};

ArrayBase.Index.displayName = "ArrayIndex";

const useAddition = (method?: "push" | "unshift", defaultValue?: any) => {
  const self = useField();
  const array = useArray();
  let showAdd = true;
  if (!array) {
    showAdd = false;
  }
  if (
    array.field?.pattern !== "editable" &&
    array.field?.pattern !== "disabled"
  ) {
    showAdd = false;
  }

  const addItem = () => {
    if (array.props?.disabled) {
      return;
    }
    const _defaultValue = getDefaultValue(defaultValue, array.schema);

    if (method === "unshift") {
      // @ts-ignore
      array.field.__arrayOperation = { action: 'add', location: 0 }
      array.field?.unshift?.(_defaultValue);
      array.props?.onAdd?.(0);
    } else {
      // @ts-ignore
      array.field.__arrayOperation = { action: 'add', location: array?.field?.value?.length ? array?.field?.value?.length : 0 }
      array.field?.push?.(_defaultValue);
      array.props?.onAdd?.(array?.field?.value?.length - 1);
    }
  };

  return {
    addItem,
    showAdd,
    disabled: self.disabled || array.props.disabled,
    currentCount: array?.field?.value?.length ?? 0,
    title: self.title,
  };
};

ArrayBase.useAddition = useAddition;

ArrayBase.Addition = (props) => {
  const { addItem, showAdd, disabled, title, currentCount } = useAddition(
    props.method,
    props.defaultValue
  );
  const prefixCls = usePrefixCls("formily-array-base");
  if (!showAdd) {
    return null;
  }
  return (
    <Button
      type="dashed"
      // style={currentCount === 0 ? { marginTop: "0px" } : { marginTop: "20px" }}
      {...props}
      disabled={disabled}
      className={cls(`${prefixCls}-addition`, props.className)}
      onClick={(e) => {
        addItem();
        if (props.onClick) {
          props.onClick(e);
        }
      }}
      icon={<IconPlus />}
    >
      {props.title || title}
    </Button>
  );
};

ArrayBase.Addition.displayName = "ArrayAddition";

ArrayBase.Copy = React.forwardRef((props, ref) => {
  const self = useField();
  const array = useArray();
  const index = useIndex(props.index);
  const prefixCls = usePrefixCls("formily-array-base");
  if (!array) {
    return null;
  }
  if (array.field?.pattern !== "editable") {
    return null;
  }
  return (
    <IconCopy
      {...props}
      className={cls(
        `${prefixCls}-copy`,
        self?.disabled ? `${prefixCls}-copy-disabled` : "",
        props.className
      )}
      ref={ref}
      onClick={(e) => {
        if (self?.disabled) {
          return;
        }
        e.stopPropagation();
        if (array.props?.disabled) {
          return;
        }
        const value = clone(array?.field?.value[index]);
        const distIndex = index + 1;
        // @ts-ignore
        array.field.__arrayOperation = { action: 'add', location: distIndex }
        array.field?.insert?.(distIndex, value);
        array.props?.onCopy?.(distIndex);
        if (props.onClick) {
          props.onClick(e);
        }
      }}
    />
  );
});

ArrayBase.Copy.displayName = "ArrayCopy";

const useRemove = (index?: number) => {
  const _index = useIndex(index);
  const self = useField();
  const array = useArray();

  let showRemove = true;

  if (!array) {
    showRemove = false;
  }
  if (array.field?.pattern !== "editable") {
    showRemove = false;
  }

  const removeItem = () => {
    // @ts-ignore
    array.field.__arrayOperation = { action: 'remove', location: _index }
    array.field?.remove?.(_index);
    array.props?.onRemove?.(_index);
  };

  return { removeItem, showRemove, index: _index, disabled: self?.disabled };
};

ArrayBase.useRemove = useRemove;

ArrayBase.Remove = React.forwardRef((props, ref) => {
  const { removeItem, showRemove, disabled } = useRemove(props.index);
  const prefixCls = usePrefixCls("formily-array-base");
  if (!showRemove) {
    return null;
  }
  return (
    <IconDelete
      {...props}
      className={cls(
        `${prefixCls}-remove`,
        disabled ? `${prefixCls}-remove-disabled` : "",
        props.className
      )}
      ref={ref}
      onClick={(e) => {
        if (disabled) {
          return;
        }
        e.stopPropagation();
        removeItem();
        if (props.onClick) {
          props.onClick(e);
        }
      }}
    />
  );
});

ArrayBase.Remove.displayName = "ArrayRemove";

ArrayBase.MoveDown = React.forwardRef((props, ref) => {
  const index = useIndex(props.index);
  const self = useField();
  const array = useArray();
  const prefixCls = usePrefixCls("formily-array-base");
  if (!array) {
    return null;
  }
  if (array.field?.pattern !== "editable") {
    return null;
  }
  return (
    <IconDown
      {...props}
      className={cls(
        `${prefixCls}-move-down`,
        self?.disabled ? `${prefixCls}-move-down-disabled` : "",
        props.className
      )}
      ref={ref}
      onClick={(e) => {
        if (self?.disabled) {
          return;
        }
        e.stopPropagation();
        // @ts-ignore
        array.field.__arrayOperation = { action: 'move', location: { old: index, new: index - 1 } }
        array.field?.moveDown?.(index);
        array.props?.onMoveDown?.(index);
        if (props.onClick) {
          props.onClick(e);
        }
      }}
    />
  );
});

ArrayBase.MoveDown.displayName = "ArrayMoveDown";

ArrayBase.MoveUp = React.forwardRef((props, ref) => {
  const index = useIndex(props.index);
  const self = useField();
  const array = useArray();
  const prefixCls = usePrefixCls("formily-array-base");
  if (!array) {
    return null;
  }
  if (array.field?.pattern !== "editable") {
    return null;
  }
  return (
    <IconUp
      {...props}
      className={cls(
        `${prefixCls}-move-up`,
        self?.disabled ? `${prefixCls}-move-up-disabled` : "",
        props.className
      )}
      ref={ref}
      onClick={(e) => {
        if (self?.disabled) {
          return;
        }
        e.stopPropagation();
        // @ts-ignore
        array.field.__arrayOperation = { action: 'move', location: { old: index, new: index + 1 } }
        array?.field?.moveUp(index);
        array?.props?.onMoveUp?.(index);
        if (props.onClick) {
          props.onClick(e);
        }
      }}
    />
  );
});

ArrayBase.MoveUp.displayName = "ArrayMoveUp";

ArrayBase.useArray = useArray;
ArrayBase.useIndex = useIndex;
ArrayBase.useRecord = useRecord;
ArrayBase.mixin = (target: any) => {
  target.Index = ArrayBase.Index;
  target.SortHandle = ArrayBase.SortHandle;
  target.Addition = ArrayBase.Addition;
  target.Copy = ArrayBase.Copy;
  target.Remove = ArrayBase.Remove;
  target.MoveDown = ArrayBase.MoveDown;
  target.MoveUp = ArrayBase.MoveUp;
  target.useArray = ArrayBase.useArray;
  target.useIndex = ArrayBase.useIndex;
  target.useRecord = ArrayBase.useRecord;
  target.useAddition = ArrayBase.useAddition;
  target.useRemove = ArrayBase.useRemove;
  return target;
};

export default ArrayBase;
